<template>
    <div>
        <Head title="Alertify" />

        <h3 class="title text-center">Alertify</h3>
        <div class="row">
            <div v-for="example in examples" :key="example.id" class="md:col-3">
                <Card>
                    <div class="text-center">
                        <h5 class="card-text">{{ example.title }}</h5>
                        <button
                            type="button"
                            class="btn btn-rose"
                            :aria-label="`Try: ${example.title}`"
                            @click="showExample(example.id)"
                        >
                            Try me!
                        </button>
                    </div>
                </Card>
            </div>
        </div>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';

export default {
    name: 'AlertifyDemo',
    components: { Card, Head },
    layout: { pageTitle: 'Alertify' },
    data() {
        return {
            closeTimer: null,
            examples: [
                { id: 'basic', title: 'Basic example' },
                { id: 'title-and-text', title: 'A title with text underneath' },
                { id: 'success', title: 'A success message' },
                { id: 'html', title: 'Custom HTML description' },
                { id: 'confirm', title: 'A warning with a confirmation callback' },
                { id: 'cancel', title: 'A warning with a cancellation callback' },
                { id: 'timer', title: 'Automatically closes after 2 seconds' },
                { id: 'prompt', title: 'Modal window with an input field' },
            ],
        };
    },
    beforeUnmount() {
        clearTimeout(this.closeTimer);
    },
    methods: {
        async showExample(example) {
            const { default: alertify } = await import('alertifyjs');
            clearTimeout(this.closeTimer);

            switch (example) {
                case 'basic':
                    alertify.alert('Here’s a message!');
                    break;
                case 'title-and-text':
                    alertify.alert('Here’s a message!', 'It’s pretty, isn’t it?');
                    break;
                case 'success':
                    alertify.alert('Good job!', 'You clicked the button!');
                    break;
                case 'html':
                    alertify.alert('HTML example', 'You can use <strong>bold text</strong> and <em>other HTML tags</em>.');
                    break;
                case 'confirm':
                case 'cancel':
                    alertify.confirm(
                        'Are you sure?',
                        'This will delete an imaginary file.',
                        () => alertify.success('Your imaginary file has been deleted.'),
                        () => {
                            if (example === 'cancel') {
                                alertify.message('Your imaginary file is safe.');
                            }
                        },
                    );
                    break;
                case 'timer': {
                    const dialog = alertify.alert('Auto-close alert', 'I will close in 2 seconds.');
                    this.closeTimer = setTimeout(() => dialog.close(), 2000);
                    break;
                }
                case 'prompt':
                    alertify.prompt('Input something', 'Enter a value:', '', (_event, value) => {
                        const message = document.createElement('span');
                        message.textContent = `You entered: ${value}`;
                        alertify.alert('Input received', message);
                    }, () => {});
                    break;
            }
        },
    },
};
</script>
